USE hunter_wallet;
ALTER TABLE video_categories ADD COLUMN character_name VARCHAR(190) NULL, ADD COLUMN character_asset_url VARCHAR(500) NULL, ADD COLUMN channel_url VARCHAR(500) NULL, ADD COLUMN teaser_video_id VARCHAR(80) NULL, ADD COLUMN broadcast_message VARCHAR(500) NULL, ADD COLUMN overlay_asset_url VARCHAR(500) NULL, ADD COLUMN capacity_limit INT UNSIGNED NOT NULL DEFAULT 500;
CREATE TABLE IF NOT EXISTS category_broadcasts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,topic VARCHAR(120) NOT NULL,message VARCHAR(500) NOT NULL,status ENUM('QUEUED','SENT','FAILED') NOT NULL DEFAULT 'QUEUED',provider_reference VARCHAR(190) NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,FOREIGN KEY(category_id) REFERENCES video_categories(id),FOREIGN KEY(created_by) REFERENCES admins(id),INDEX idx_category_broadcast(category_id,status,created_at)) ENGINE=InnoDB;
ALTER TABLE vendors ADD COLUMN kyc_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', ADD COLUMN kyc_document_path VARCHAR(255) NULL;
CREATE TABLE IF NOT EXISTS qr_batches (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_code VARCHAR(60) NOT NULL UNIQUE,batch_title VARCHAR(190) NOT NULL,category ENUM('VIDEO_PAHELI','PRODUCT_SKU','COUPON_VOUCHER','BONUS_POINT') NOT NULL,generation_mode ENUM('UPLOAD','AUTO_COUNT') NOT NULL,quantity INT UNSIGNED NOT NULL,scan_frequency ENUM('SINGLE_USE','PER_DEVICE','DAILY','POOL') NOT NULL DEFAULT 'PER_DEVICE',reward_type VARCHAR(40) NOT NULL,reward_value DECIMAL(18,2) NOT NULL DEFAULT 0,status ENUM('ACTIVE','PAUSED','DEACTIVATED','COMPLETED') NOT NULL DEFAULT 'ACTIVE',hunt_id BIGINT UNSIGNED NULL,location_id BIGINT UNSIGNED NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_qr_batch_status(status),FOREIGN KEY(hunt_id) REFERENCES hunts(id),FOREIGN KEY(location_id) REFERENCES hunt_locations(id),FOREIGN KEY(created_by) REFERENCES admins(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS qr_batch_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT UNSIGNED NOT NULL,spot_id VARCHAR(80) NOT NULL UNIQUE,spot_name VARCHAR(190) NOT NULL,category_tag VARCHAR(120) NULL,riddle_text TEXT NULL,youtube_video_id VARCHAR(40) NULL,correct_answer_hash CHAR(64) NULL,reward_type VARCHAR(40) NOT NULL,reward_value DECIMAL(18,2) NOT NULL DEFAULT 0,timer_ttl_minutes INT UNSIGNED NULL,qr_code_id BIGINT UNSIGNED NULL,encrypted_url VARCHAR(500) NOT NULL,status ENUM('ACTIVE','PAUSED','DEACTIVATED','SCANNED') NOT NULL DEFAULT 'ACTIVE',scanned_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_qr_batch_item(batch_id,status),FOREIGN KEY(batch_id) REFERENCES qr_batches(id) ON DELETE CASCADE,FOREIGN KEY(qr_code_id) REFERENCES hunt_qr_codes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS staff_profiles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,admin_id INT UNSIGNED NOT NULL UNIQUE,mobile VARCHAR(30) NOT NULL UNIQUE,address VARCHAR(500) NULL,designation VARCHAR(120) NULL,aadhaar_front_path VARCHAR(255) NULL,aadhaar_back_path VARCHAR(255) NULL,pan_path VARCHAR(255) NULL,photo_path VARCHAR(255) NULL,kyc_status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',approved_by INT UNSIGNED NULL,approved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(admin_id) REFERENCES admins(id) ON DELETE CASCADE,FOREIGN KEY(approved_by) REFERENCES admins(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin_otp_challenges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mobile VARCHAR(30) NOT NULL,admin_id INT UNSIGNED NULL,otp_hash CHAR(64) NOT NULL,purpose ENUM('LOGIN','KYC') NOT NULL DEFAULT 'LOGIN',attempts TINYINT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL,consumed_at DATETIME NULL,ip_address VARCHAR(45) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_admin_otp(mobile,purpose,expires_at),FOREIGN KEY(admin_id) REFERENCES admins(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS coupons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code_hash CHAR(64) NOT NULL UNIQUE,code_reference VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,discount_amount DECIMAL(18,2) NOT NULL,min_cart_amount DECIMAL(18,2) NOT NULL DEFAULT 0,merchant_id BIGINT UNSIGNED NULL,ttl_minutes INT UNSIGNED NULL,expires_at DATETIME NULL,status ENUM('ACTIVE','USED','EXPIRED','CANCELLED') NOT NULL DEFAULT 'ACTIVE',user_id BIGINT UNSIGNED NULL,used_at DATETIME NULL,created_by INT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(merchant_id) REFERENCES vendors(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(created_by) REFERENCES admins(id),INDEX idx_coupon_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS merchant_settlements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,settlement_id VARCHAR(60) NOT NULL UNIQUE,checkout_id VARCHAR(50) NOT NULL UNIQUE,merchant_id BIGINT UNSIGNED NOT NULL,bill_amount DECIMAL(18,2) NOT NULL,promo_amount DECIMAL(18,2) NOT NULL DEFAULT 0,customer_paid DECIMAL(18,2) NOT NULL DEFAULT 0,platform_fee DECIMAL(18,2) NOT NULL DEFAULT 0,merchant_amount DECIMAL(18,2) NOT NULL DEFAULT 0,status ENUM('PENDING','SETTLED','REVERSED') NOT NULL DEFAULT 'PENDING',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,settled_at DATETIME NULL,FOREIGN KEY(merchant_id) REFERENCES vendors(id),INDEX idx_settlement_status(status,created_at)) ENGINE=InnoDB;
INSERT IGNORE INTO admin_permissions(code,description) VALUES ('vendors.kyc.approve','Approve vendor KYC'),('video.upload','Upload/edit media'),('qr.generate','Generate bulk QR'),('qr.download','Download bulk QR files'),('payouts.process','Process vendor payouts'),('staff.kyc','Manage staff KYC'),('staff.otp','Manage staff OTP');
